export const questions: Question[] = [
  {"id":"y2pe2-001","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 21","difficulty":"Standard","questionText":"Convert the parametric equations \\(x = 2\\cos\\theta,\\ y = 3\\sin\\theta\\) to Cartesian form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","trig"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2\\theta + \\sin^2\\theta = 1","explanation":"We want a relation in \\(x\\) and \\(y\\) only, but \\(\\theta\\) sits inside the trig functions. The route out is the Pythagorean identity \\(\\cos^2\\theta + \\sin^2\\theta = 1\\), which needs \\(\\cos\\theta\\) and \\(\\sin\\theta\\) on their own first."},{"stepNumber":2,"description":"Isolate \\(\\cos\\theta\\).","workingLatex":"\\cos\\theta = \\tfrac{x}{2}","explanation":"Divide \\(x = 2\\cos\\theta\\) by 2 so the right-hand side is a bare \\(\\cos\\theta\\)."},{"stepNumber":3,"description":"Isolate \\(\\sin\\theta\\).","workingLatex":"\\sin\\theta = \\tfrac{y}{3}","explanation":"Divide \\(y = 3\\sin\\theta\\) by 3 likewise."},{"stepNumber":4,"description":"Square each.","workingLatex":"\\cos^2\\theta = \\tfrac{x^2}{4},\\quad \\sin^2\\theta = \\tfrac{y^2}{9}","explanation":"Square both because the identity uses squared terms; squaring also removes any sign ambiguity."},{"stepNumber":5,"description":"Add and apply the identity.","workingLatex":"\\tfrac{x^2}{4} + \\tfrac{y^2}{9} = \\cos^2\\theta + \\sin^2\\theta = 1","explanation":"Adding the two squared equations gives exactly \\(\\cos^2\\theta + \\sin^2\\theta\\), which is 1, so \\(\\theta\\) is gone."},{"stepNumber":6,"description":"State the curve.","workingLatex":"\\tfrac{x^2}{4} + \\tfrac{y^2}{9} = 1","explanation":"An ellipse with semi-axes 2 (in \\(x\\)) and 3 (in \\(y\\))."}],"finalAnswer":"\\(\\tfrac{x^2}{4} + \\tfrac{y^2}{9} = 1\\)."}},
  {"id":"y2pe2-002","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 01","difficulty":"Foundation","questionText":"Convert the parametric equations \\(x = \\cos t,\\ y = \\sin t\\) to Cartesian form.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric","trig"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"Since \\(x = \\cos t\\) and \\(y = \\sin t\\) are already isolated, the Pythagorean identity can be used directly after squaring."},{"stepNumber":2,"description":"Square each equation.","workingLatex":"x^2 = \\cos^2 t,\\quad y^2 = \\sin^2 t","explanation":"Square both sides so the identity's squared terms appear."},{"stepNumber":3,"description":"Add the two results.","workingLatex":"x^2 + y^2 = \\cos^2 t + \\sin^2 t","explanation":"Adding groups the squared trig terms."},{"stepNumber":4,"description":"Apply the identity.","workingLatex":"x^2 + y^2 = 1","explanation":"\\(\\cos^2 t + \\sin^2 t = 1\\): the unit circle."}],"finalAnswer":"\\(x^2 + y^2 = 1\\)."}},
  {"id":"y2pe2-003","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 02","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = 5\\cos t,\\ y = 5\\sin t\\). Find its Cartesian equation.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric","trig"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"Both equations share the radius 5; isolate the trig functions, then use the Pythagorean identity."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\) and \\(\\sin t\\).","workingLatex":"\\cos t = \\tfrac{x}{5},\\quad \\sin t = \\tfrac{y}{5}","explanation":"Divide each equation by 5."},{"stepNumber":3,"description":"Square each.","workingLatex":"\\cos^2 t = \\tfrac{x^2}{25},\\quad \\sin^2 t = \\tfrac{y^2}{25}","explanation":"Square to match the identity."},{"stepNumber":4,"description":"Add and apply the identity.","workingLatex":"\\tfrac{x^2}{25} + \\tfrac{y^2}{25} = 1","explanation":"The sum of the squares equals \\(\\cos^2 t + \\sin^2 t = 1\\)."},{"stepNumber":5,"description":"Clear the denominator.","workingLatex":"x^2 + y^2 = 25","explanation":"Multiply through by 25 — a circle of radius 5 centred at the origin."}],"finalAnswer":"\\(x^2 + y^2 = 25\\)."}},
  {"id":"y2pe2-004","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 22","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = -1 + 4\\cos t,\\ y = 2 + 4\\sin t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","trig"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"The curve is a shifted circle; subtract the centre before using the identity."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\).","workingLatex":"\\cos t = \\tfrac{x + 1}{4}","explanation":"From \\(x = -1 + 4\\cos t\\): add 1, divide by 4."},{"stepNumber":3,"description":"Isolate \\(\\sin t\\).","workingLatex":"\\sin t = \\tfrac{y - 2}{4}","explanation":"From \\(y = 2 + 4\\sin t\\): subtract 2, divide by 4."},{"stepNumber":4,"description":"Square and add.","workingLatex":"\\left(\\tfrac{x + 1}{4}\\right)^2 + \\left(\\tfrac{y - 2}{4}\\right)^2 = 1","explanation":"Apply the identity to the squared, isolated functions."},{"stepNumber":5,"description":"Clear denominators.","workingLatex":"(x + 1)^2 + (y - 2)^2 = 16","explanation":"Multiply by \\(4^2 = 16\\) — a circle of radius 4 centred at \\((-1, 2)\\)."}],"finalAnswer":"\\((x + 1)^2 + (y - 2)^2 = 16\\)."}},
  {"id":"y2pe2-005","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 23","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 3 + 2\\cos t,\\ y = -1 + 2\\sin t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","trig"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"A shifted circle: subtract the centre coordinates, then use the identity."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\).","workingLatex":"\\cos t = \\tfrac{x - 3}{2}","explanation":"From \\(x = 3 + 2\\cos t\\): subtract 3, divide by 2."},{"stepNumber":3,"description":"Isolate \\(\\sin t\\).","workingLatex":"\\sin t = \\tfrac{y + 1}{2}","explanation":"From \\(y = -1 + 2\\sin t\\): add 1, divide by 2."},{"stepNumber":4,"description":"Square and add.","workingLatex":"\\left(\\tfrac{x - 3}{2}\\right)^2 + \\left(\\tfrac{y + 1}{2}\\right)^2 = 1","explanation":"Apply the identity."},{"stepNumber":5,"description":"Clear denominators.","workingLatex":"(x - 3)^2 + (y + 1)^2 = 4","explanation":"Multiply by 4 — a circle of radius 2 centred at \\((3, -1)\\)."}],"finalAnswer":"\\((x - 3)^2 + (y + 1)^2 = 4\\)."}},
  {"id":"y2pe2-006","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 24","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 4\\cos\\theta,\\ y = 3\\sin\\theta\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","trig","ellipse"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2\\theta + \\sin^2\\theta = 1","explanation":"We want a relation in \\(x\\) and \\(y\\) only, but \\(\\theta\\) sits inside the trig functions. The route out is the Pythagorean identity \\(\\cos^2\\theta + \\sin^2\\theta = 1\\), which needs \\(\\cos\\theta\\) and \\(\\sin\\theta\\) on their own first."},{"stepNumber":2,"description":"Isolate \\(\\cos\\theta\\).","workingLatex":"\\cos\\theta = \\tfrac{x}{4}","explanation":"Divide \\(x = 4\\cos\\theta\\) by 4."},{"stepNumber":3,"description":"Isolate \\(\\sin\\theta\\).","workingLatex":"\\sin\\theta = \\tfrac{y}{3}","explanation":"Divide \\(y = 3\\sin\\theta\\) by 3."},{"stepNumber":4,"description":"Square and add.","workingLatex":"\\tfrac{x^2}{16} + \\tfrac{y^2}{9} = \\cos^2\\theta + \\sin^2\\theta = 1","explanation":"Square each, add, and apply the identity."},{"stepNumber":5,"description":"State the curve.","workingLatex":"\\tfrac{x^2}{16} + \\tfrac{y^2}{9} = 1","explanation":"An ellipse with semi-axes 4 and 3."}],"finalAnswer":"\\(\\tfrac{x^2}{16} + \\tfrac{y^2}{9} = 1\\)."}},
  {"id":"y2pe2-007","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 25","difficulty":"Standard","questionText":"Convert the parametric equations \\(x = 2 + 5\\cos t,\\ y = 3 + 4\\sin t\\) to Cartesian form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","trig","ellipse"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"A shifted ellipse: subtract the centre, divide by the semi-axes, then use the identity."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\).","workingLatex":"\\cos t = \\tfrac{x - 2}{5}","explanation":"From \\(x = 2 + 5\\cos t\\)."},{"stepNumber":3,"description":"Isolate \\(\\sin t\\).","workingLatex":"\\sin t = \\tfrac{y - 3}{4}","explanation":"From \\(y = 3 + 4\\sin t\\)."},{"stepNumber":4,"description":"Square and add.","workingLatex":"\\left(\\tfrac{x - 2}{5}\\right)^2 + \\left(\\tfrac{y - 3}{4}\\right)^2 = 1","explanation":"Apply the identity to the isolated, squared functions."},{"stepNumber":5,"description":"State the ellipse.","workingLatex":"\\tfrac{(x - 2)^2}{25} + \\tfrac{(y - 3)^2}{16} = 1","explanation":"Centre \\((2, 3)\\), semi-axes 5 and 4."}],"finalAnswer":"\\(\\tfrac{(x - 2)^2}{25} + \\tfrac{(y - 3)^2}{16} = 1\\)."}},
  {"id":"y2pe2-008","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 26","difficulty":"Standard","questionText":"Convert the parametric equations \\(x = \\sec t,\\ y = \\tan t\\) to Cartesian form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","trig","hyperbola"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"1 + \\tan^2 t = \\sec^2 t \\;\\Rightarrow\\; \\sec^2 t - \\tan^2 t = 1","explanation":"With \\(\\sec\\) and \\(\\tan\\) present, the relevant identity is \\(\\sec^2 - \\tan^2 = 1\\), not \\(\\cos^2 + \\sin^2\\)."},{"stepNumber":2,"description":"Note the isolated functions.","workingLatex":"x = \\sec t,\\quad y = \\tan t","explanation":"Both trig functions are already on their own — no rearranging needed."},{"stepNumber":3,"description":"Square each.","workingLatex":"x^2 = \\sec^2 t,\\quad y^2 = \\tan^2 t","explanation":"Square to match the squared terms in the identity."},{"stepNumber":4,"description":"Subtract and apply the identity.","workingLatex":"x^2 - y^2 = \\sec^2 t - \\tan^2 t = 1","explanation":"Subtracting (not adding) is what the sec–tan identity requires."},{"stepNumber":5,"description":"State the curve.","workingLatex":"x^2 - y^2 = 1","explanation":"A rectangular hyperbola."}],"finalAnswer":"\\(x^2 - y^2 = 1\\)."}},
  {"id":"y2pe2-009","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 27","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 2\\sec t,\\ y = 3\\tan t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","hyperbola"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"Sec and tan call for \\(\\sec^2 - \\tan^2 = 1\\)."},{"stepNumber":2,"description":"Isolate \\(\\sec t\\) and \\(\\tan t\\).","workingLatex":"\\sec t = \\tfrac{x}{2},\\quad \\tan t = \\tfrac{y}{3}","explanation":"Divide each equation by its coefficient."},{"stepNumber":3,"description":"Square each.","workingLatex":"\\sec^2 t = \\tfrac{x^2}{4},\\quad \\tan^2 t = \\tfrac{y^2}{9}","explanation":"Square the isolated functions."},{"stepNumber":4,"description":"Subtract and apply the identity.","workingLatex":"\\tfrac{x^2}{4} - \\tfrac{y^2}{9} = 1","explanation":"\\(\\sec^2 t - \\tan^2 t = 1\\)."},{"stepNumber":5,"description":"State the curve.","workingLatex":"\\tfrac{x^2}{4} - \\tfrac{y^2}{9} = 1","explanation":"A hyperbola opening left–right."}],"finalAnswer":"\\(\\tfrac{x^2}{4} - \\tfrac{y^2}{9} = 1\\)."}},
  {"id":"y2pe2-010","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 28","difficulty":"Standard","questionText":"Convert the parametric equations \\(x = \\csc t,\\ y = \\cot t\\) to Cartesian form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","hyperbola"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\csc^2 t - \\cot^2 t = 1","explanation":"Dividing \\(\\sin^2 + \\cos^2 = 1\\) by \\(\\sin^2 t\\) gives \\(1 + \\cot^2 t = \\csc^2 t\\), i.e. \\(\\csc^2 - \\cot^2 = 1\\)."},{"stepNumber":2,"description":"Note the isolated functions.","workingLatex":"x = \\csc t,\\quad y = \\cot t","explanation":"Both are already on their own."},{"stepNumber":3,"description":"Square each.","workingLatex":"x^2 = \\csc^2 t,\\quad y^2 = \\cot^2 t","explanation":"Square to match the identity."},{"stepNumber":4,"description":"Subtract and apply the identity.","workingLatex":"x^2 - y^2 = \\csc^2 t - \\cot^2 t = 1","explanation":"Subtract to use the identity."},{"stepNumber":5,"description":"State the curve.","workingLatex":"x^2 - y^2 = 1","explanation":"A hyperbola."}],"finalAnswer":"\\(x^2 - y^2 = 1\\)."}},
  {"id":"y2pe2-011","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 51","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = \\sin\\theta,\\ y = \\cos 2\\theta\\) to Cartesian form.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric","double angle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Pick the useful form of \\(\\cos 2\\theta\\).","workingLatex":"\\cos 2\\theta = 1 - 2\\sin^2\\theta","explanation":"\\(\\cos 2\\theta\\) has three forms; choose the one in \\(\\sin\\theta\\) because \\(x = \\sin\\theta\\)."},{"stepNumber":2,"description":"Rewrite \\(y\\).","workingLatex":"y = 1 - 2\\sin^2\\theta","explanation":"Substitute that form into \\(y = \\cos 2\\theta\\)."},{"stepNumber":3,"description":"Substitute \\(x = \\sin\\theta\\).","workingLatex":"y = 1 - 2x^2","explanation":"Replace \\(\\sin\\theta\\) by \\(x\\); the parameter is eliminated."},{"stepNumber":4,"description":"State the curve.","workingLatex":"y = 1 - 2x^2","explanation":"A downward parabola (restricted to \\(-1 \\le x \\le 1\\))."}],"finalAnswer":"\\(y = 1 - 2x^2\\)."}},
  {"id":"y2pe2-012","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 29","difficulty":"Standard","questionText":"Convert the parametric equations \\(x = \\cos t,\\ y = \\cos 2t\\) to Cartesian form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","double angle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Pick the useful form of \\(\\cos 2t\\).","workingLatex":"\\cos 2t = 2\\cos^2 t - 1","explanation":"Choose the \\(\\cos^2 t\\) form because \\(x = \\cos t\\)."},{"stepNumber":2,"description":"Rewrite \\(y\\).","workingLatex":"y = 2\\cos^2 t - 1","explanation":"Substitute into \\(y = \\cos 2t\\)."},{"stepNumber":3,"description":"Substitute \\(x = \\cos t\\).","workingLatex":"y = 2x^2 - 1","explanation":"Replace \\(\\cos t\\) by \\(x\\)."},{"stepNumber":4,"description":"State the curve.","workingLatex":"y = 2x^2 - 1","explanation":"An upward parabola (with \\(-1 \\le x \\le 1\\))."}],"finalAnswer":"\\(y = 2x^2 - 1\\)."}},
  {"id":"y2pe2-013","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 30","difficulty":"Standard","questionText":"Convert the parametric equations \\(x = 2\\sin\\theta,\\ y = \\cos 2\\theta\\) to Cartesian form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","double angle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Pick the useful form of \\(\\cos 2\\theta\\).","workingLatex":"\\cos 2\\theta = 1 - 2\\sin^2\\theta","explanation":"Use the \\(\\sin\\theta\\) form since \\(x\\) involves \\(\\sin\\theta\\)."},{"stepNumber":2,"description":"Express \\(\\sin\\theta\\) via \\(x\\).","workingLatex":"\\sin\\theta = \\tfrac{x}{2}","explanation":"From \\(x = 2\\sin\\theta\\)."},{"stepNumber":3,"description":"Substitute.","workingLatex":"y = 1 - 2\\left(\\tfrac{x}{2}\\right)^2","explanation":"Put \\(\\sin\\theta = \\tfrac{x}{2}\\) into \\(y = 1 - 2\\sin^2\\theta\\)."},{"stepNumber":4,"description":"Simplify.","workingLatex":"y = 1 - \\tfrac{x^2}{2}","explanation":"\\(2 \\cdot \\tfrac{x^2}{4} = \\tfrac{x^2}{2}\\)."}],"finalAnswer":"\\(y = 1 - \\tfrac{x^2}{2}\\)."}},
  {"id":"y2pe2-014","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 52","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = \\sin t,\\ y = \\sin 2t\\) to Cartesian form.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric","double angle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Expand the double angle.","workingLatex":"\\sin 2t = 2\\sin t\\cos t","explanation":"Use the product form of \\(\\sin 2t\\) because both \\(\\sin t\\) and \\(\\cos t\\) can be tied to \\(x\\)."},{"stepNumber":2,"description":"Substitute \\(\\sin t = x\\).","workingLatex":"y = 2x\\cos t","explanation":"Since \\(x = \\sin t\\). One factor is now \\(x\\); deal with \\(\\cos t\\) next."},{"stepNumber":3,"description":"Express \\(\\cos t\\) via \\(x\\).","workingLatex":"\\cos t = \\pm\\sqrt{1 - x^2}","explanation":"From \\(\\sin^2 t + \\cos^2 t = 1\\); both signs are possible."},{"stepNumber":4,"description":"Substitute and square to remove the \\(\\pm\\).","workingLatex":"y^2 = 4x^2\\cos^2 t = 4x^2(1 - x^2)","explanation":"Square \\(y = 2x\\cos t\\) and replace \\(\\cos^2 t = 1 - x^2\\); squaring clears the sign."},{"stepNumber":5,"description":"State the curve.","workingLatex":"y^2 = 4x^2(1 - x^2)","explanation":"A figure-eight (lemniscate-like) curve."}],"finalAnswer":"\\(y^2 = 4x^2(1 - x^2)\\)."}},
  {"id":"y2pe2-015","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 53","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = \\cos 2t,\\ y = \\sin t\\) to Cartesian form.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric","double angle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Pick the useful form of \\(\\cos 2t\\).","workingLatex":"\\cos 2t = 1 - 2\\sin^2 t","explanation":"Choose the \\(\\sin t\\) form because \\(y = \\sin t\\)."},{"stepNumber":2,"description":"Rewrite \\(x\\).","workingLatex":"x = 1 - 2\\sin^2 t","explanation":"Substitute into \\(x = \\cos 2t\\)."},{"stepNumber":3,"description":"Substitute \\(y = \\sin t\\).","workingLatex":"x = 1 - 2y^2","explanation":"Replace \\(\\sin t\\) by \\(y\\)."},{"stepNumber":4,"description":"State the curve.","workingLatex":"x = 1 - 2y^2","explanation":"A sideways parabola."}],"finalAnswer":"\\(x = 1 - 2y^2\\)."}},
  {"id":"y2pe2-016","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 54","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = \\cos 2t,\\ y = \\cos t\\) to Cartesian form.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric","double angle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Pick the useful form of \\(\\cos 2t\\).","workingLatex":"\\cos 2t = 2\\cos^2 t - 1","explanation":"Use the \\(\\cos^2 t\\) form because \\(y = \\cos t\\)."},{"stepNumber":2,"description":"Rewrite \\(x\\).","workingLatex":"x = 2\\cos^2 t - 1","explanation":"Substitute into \\(x = \\cos 2t\\)."},{"stepNumber":3,"description":"Substitute \\(y = \\cos t\\).","workingLatex":"x = 2y^2 - 1","explanation":"Replace \\(\\cos t\\) by \\(y\\)."},{"stepNumber":4,"description":"State the curve.","workingLatex":"x = 2y^2 - 1","explanation":"A sideways parabola."}],"finalAnswer":"\\(x = 2y^2 - 1\\)."}},
  {"id":"y2pe2-017","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 55","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = \\tan t,\\ y = \\sin 2t\\) to Cartesian form.","marks":5,"examStyle":true,"yearCreated":2026,"tags":["parametric","double angle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Recall the \\(t\\)-formula.","workingLatex":"\\sin 2t = \\tfrac{2\\tan t}{1 + \\tan^2 t}","explanation":"Writing \\(\\sin 2t\\) through \\(\\tan t\\) lets us substitute \\(x = \\tan t\\) in one step."},{"stepNumber":2,"description":"Substitute \\(\\tan t = x\\).","workingLatex":"y = \\tfrac{2x}{1 + x^2}","explanation":"Replace \\(\\tan t\\) by \\(x\\)."},{"stepNumber":3,"description":"State the curve.","workingLatex":"y = \\tfrac{2x}{1 + x^2}","explanation":"A bell-shaped rational curve (range \\(-1 \\le y \\le 1\\))."}],"finalAnswer":"\\(y = \\tfrac{2x}{1 + x^2}\\)."}},
  {"id":"y2pe2-018","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 56","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = \\tan t,\\ y = \\cos 2t\\) to Cartesian form.","marks":5,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Recall the \\(t\\)-formula.","workingLatex":"\\cos 2t = \\tfrac{1 - \\tan^2 t}{1 + \\tan^2 t}","explanation":"Expressing \\(\\cos 2t\\) through \\(\\tan t\\) suits \\(x = \\tan t\\)."},{"stepNumber":2,"description":"Substitute \\(\\tan t = x\\).","workingLatex":"y = \\tfrac{1 - x^2}{1 + x^2}","explanation":"Replace \\(\\tan t\\) by \\(x\\)."},{"stepNumber":3,"description":"State the curve.","workingLatex":"y = \\tfrac{1 - x^2}{1 + x^2}","explanation":"A rational curve with horizontal asymptote \\(y = -1\\)."}],"finalAnswer":"\\(y = \\tfrac{1 - x^2}{1 + x^2}\\)."}},
  {"id":"y2pe2-019","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 57","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = \\tan\\theta,\\ y = \\tan 2\\theta\\) to Cartesian form.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Recall the double-angle tangent formula.","workingLatex":"\\tan 2\\theta = \\tfrac{2\\tan\\theta}{1 - \\tan^2\\theta}","explanation":"This expresses \\(\\tan 2\\theta\\) through \\(\\tan\\theta\\)."},{"stepNumber":2,"description":"Substitute \\(\\tan\\theta = x\\).","workingLatex":"y = \\tfrac{2x}{1 - x^2}","explanation":"Replace \\(\\tan\\theta\\) by \\(x\\)."},{"stepNumber":3,"description":"State the curve.","workingLatex":"y = \\tfrac{2x}{1 - x^2}","explanation":"A rational curve with vertical asymptotes at \\(x = \\pm 1\\)."}],"finalAnswer":"\\(y = \\tfrac{2x}{1 - x^2}\\)."}},
  {"id":"y2pe2-020","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 03","difficulty":"Foundation","questionText":"Convert the parametric equations \\(x = \\cos^2 t,\\ y = \\sin^2 t\\) to Cartesian form.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Spot the direct identity.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"Here \\(x = \\cos^2 t\\) and \\(y = \\sin^2 t\\) are already the squared functions — no squaring needed."},{"stepNumber":2,"description":"Add the equations.","workingLatex":"x + y = \\cos^2 t + \\sin^2 t","explanation":"Adding builds the identity immediately."},{"stepNumber":3,"description":"Apply the identity.","workingLatex":"x + y = 1","explanation":"\\(\\cos^2 t + \\sin^2 t = 1\\)."},{"stepNumber":4,"description":"Note the restriction.","workingLatex":"0 \\le x \\le 1,\\ 0 \\le y \\le 1","explanation":"Because \\(\\cos^2,\\sin^2 \\in [0,1]\\), only the segment of \\(x + y = 1\\) in the unit square is traced."}],"finalAnswer":"\\(x + y = 1\\)."}},
  {"id":"y2pe2-021","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 31","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 1 + 2\\cos\\theta,\\ y = -3 + 5\\sin\\theta\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","ellipse"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2\\theta + \\sin^2\\theta = 1","explanation":"A shifted ellipse: subtract the centre, divide by the semi-axes, then use the identity."},{"stepNumber":2,"description":"Isolate \\(\\cos\\theta\\).","workingLatex":"\\cos\\theta = \\tfrac{x - 1}{2}","explanation":"From \\(x = 1 + 2\\cos\\theta\\)."},{"stepNumber":3,"description":"Isolate \\(\\sin\\theta\\).","workingLatex":"\\sin\\theta = \\tfrac{y + 3}{5}","explanation":"From \\(y = -3 + 5\\sin\\theta\\)."},{"stepNumber":4,"description":"Square and add.","workingLatex":"\\left(\\tfrac{x - 1}{2}\\right)^2 + \\left(\\tfrac{y + 3}{5}\\right)^2 = 1","explanation":"Apply the identity."},{"stepNumber":5,"description":"State the ellipse.","workingLatex":"\\tfrac{(x - 1)^2}{4} + \\tfrac{(y + 3)^2}{25} = 1","explanation":"Centre \\((1, -3)\\), semi-axes 2 and 5."}],"finalAnswer":"\\(\\tfrac{(x - 1)^2}{4} + \\tfrac{(y + 3)^2}{25} = 1\\)."}},
  {"id":"y2pe2-022","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 32","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 4 + 3\\cos\\theta,\\ y = 2 + 3\\sin\\theta\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","circle"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2\\theta + \\sin^2\\theta = 1","explanation":"A shifted circle of radius 3."},{"stepNumber":2,"description":"Isolate \\(\\cos\\theta\\).","workingLatex":"\\cos\\theta = \\tfrac{x - 4}{3}","explanation":"From \\(x = 4 + 3\\cos\\theta\\)."},{"stepNumber":3,"description":"Isolate \\(\\sin\\theta\\).","workingLatex":"\\sin\\theta = \\tfrac{y - 2}{3}","explanation":"From \\(y = 2 + 3\\sin\\theta\\)."},{"stepNumber":4,"description":"Square and add.","workingLatex":"\\left(\\tfrac{x - 4}{3}\\right)^2 + \\left(\\tfrac{y - 2}{3}\\right)^2 = 1","explanation":"Apply the identity."},{"stepNumber":5,"description":"Clear denominators.","workingLatex":"(x - 4)^2 + (y - 2)^2 = 9","explanation":"Multiply by 9 — a circle of radius 3 centred at \\((4, 2)\\)."}],"finalAnswer":"\\((x - 4)^2 + (y - 2)^2 = 9\\)."}},
  {"id":"y2pe2-023","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 58","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = 1 + \\sec t,\\ y = \\tan t\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric","hyperbola"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"Sec and tan present, so use the sec–tan identity."},{"stepNumber":2,"description":"Isolate \\(\\sec t\\) and \\(\\tan t\\).","workingLatex":"\\sec t = x - 1,\\quad \\tan t = y","explanation":"Subtract the shift from \\(x\\); \\(y\\) is already \\(\\tan t\\)."},{"stepNumber":3,"description":"Square each.","workingLatex":"\\sec^2 t = (x - 1)^2,\\quad \\tan^2 t = y^2","explanation":"Square the isolated functions."},{"stepNumber":4,"description":"Subtract and apply the identity.","workingLatex":"(x - 1)^2 - y^2 = 1","explanation":"\\(\\sec^2 t - \\tan^2 t = 1\\). A hyperbola centred at \\((1, 0)\\)."}],"finalAnswer":"\\((x - 1)^2 - y^2 = 1\\)."}},
  {"id":"y2pe2-024","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 59","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = 1 + 2\\sec t,\\ y = -2 + 3\\tan t\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"A shifted, scaled hyperbola."},{"stepNumber":2,"description":"Isolate \\(\\sec t\\).","workingLatex":"\\sec t = \\tfrac{x - 1}{2}","explanation":"From \\(x = 1 + 2\\sec t\\)."},{"stepNumber":3,"description":"Isolate \\(\\tan t\\).","workingLatex":"\\tan t = \\tfrac{y + 2}{3}","explanation":"From \\(y = -2 + 3\\tan t\\)."},{"stepNumber":4,"description":"Square and subtract.","workingLatex":"\\left(\\tfrac{x - 1}{2}\\right)^2 - \\left(\\tfrac{y + 2}{3}\\right)^2 = 1","explanation":"Apply the sec–tan identity."},{"stepNumber":5,"description":"State the hyperbola.","workingLatex":"\\tfrac{(x - 1)^2}{4} - \\tfrac{(y + 2)^2}{9} = 1","explanation":"Centre \\((1, -2)\\)."}],"finalAnswer":"\\(\\tfrac{(x - 1)^2}{4} - \\tfrac{(y + 2)^2}{9} = 1\\)."}},
  {"id":"y2pe2-025","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 04","difficulty":"Foundation","questionText":"Convert the parametric equations \\(x = \\sin t,\\ y = \\cos t\\) to Cartesian form.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\sin^2 t + \\cos^2 t = 1","explanation":"\\(x = \\sin t\\) and \\(y = \\cos t\\) are already isolated; the order in the identity does not matter."},{"stepNumber":2,"description":"Square each.","workingLatex":"x^2 = \\sin^2 t,\\quad y^2 = \\cos^2 t","explanation":"Square both."},{"stepNumber":3,"description":"Add and apply the identity.","workingLatex":"x^2 + y^2 = \\sin^2 t + \\cos^2 t = 1","explanation":"The unit circle (traced from \\((0, 1)\\) clockwise)."}],"finalAnswer":"\\(x^2 + y^2 = 1\\)."}},
  {"id":"y2pe2-026","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 60","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = \\cos t,\\ y = \\cos\\!\\left(t + \\tfrac{\\pi}{3}\\right)\\). Find its Cartesian equation.","marks":5,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Expand using the compound-angle formula.","workingLatex":"y = \\cos t\\cos\\tfrac{\\pi}{3} - \\sin t\\sin\\tfrac{\\pi}{3}","explanation":"Use \\(\\cos(A + B) = \\cos A\\cos B - \\sin A\\sin B\\) with \\(A = t,\\ B = \\tfrac{\\pi}{3}\\)."},{"stepNumber":2,"description":"Insert exact values.","workingLatex":"y = \\tfrac{1}{2}\\cos t - \\tfrac{\\sqrt 3}{2}\\sin t","explanation":"\\(\\cos\\tfrac{\\pi}{3} = \\tfrac12\\) and \\(\\sin\\tfrac{\\pi}{3} = \\tfrac{\\sqrt 3}{2}\\)."},{"stepNumber":3,"description":"Use \\(\\cos t = x\\).","workingLatex":"y = \\tfrac{x}{2} - \\tfrac{\\sqrt 3}{2}\\sin t","explanation":"Replace \\(\\cos t\\) by \\(x\\); only \\(\\sin t\\) is left to eliminate."},{"stepNumber":4,"description":"Make \\(\\sin t\\) the subject.","workingLatex":"\\sin t = \\tfrac{x - 2y}{\\sqrt 3}","explanation":"Rearrange: \\(\\tfrac{\\sqrt3}{2}\\sin t = \\tfrac{x}{2} - y\\), so \\(\\sin t = \\tfrac{x - 2y}{\\sqrt 3}\\)."},{"stepNumber":5,"description":"Apply \\(\\cos^2 t + \\sin^2 t = 1\\).","workingLatex":"x^2 + \\tfrac{(x - 2y)^2}{3} = 1","explanation":"Substitute \\(\\cos t = x\\) and \\(\\sin t = \\tfrac{x - 2y}{\\sqrt 3}\\); a rotated ellipse."}],"finalAnswer":"\\(x^2 + \\tfrac{(x - 2y)^2}{3} = 1\\)."}},
  {"id":"y2pe2-027","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 33","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = \\cos\\theta + \\sin\\theta,\\ y = \\cos\\theta - \\sin\\theta\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Decide to square and add.","workingLatex":"x^2 + y^2 = ?","explanation":"The cross terms from \\((\\cos\\theta \\pm \\sin\\theta)^2\\) will cancel when we add, leaving only \\(\\cos^2 + \\sin^2\\)."},{"stepNumber":2,"description":"Square \\(x = \\cos\\theta + \\sin\\theta\\).","workingLatex":"x^2 = \\cos^2\\theta + 2\\sin\\theta\\cos\\theta + \\sin^2\\theta","explanation":"Expand the square, keeping the middle term \\(+2\\sin\\theta\\cos\\theta\\)."},{"stepNumber":3,"description":"Square \\(y = \\cos\\theta - \\sin\\theta\\).","workingLatex":"y^2 = \\cos^2\\theta - 2\\sin\\theta\\cos\\theta + \\sin^2\\theta","explanation":"Here the middle term is \\(-2\\sin\\theta\\cos\\theta\\)."},{"stepNumber":4,"description":"Add to cancel the cross terms.","workingLatex":"x^2 + y^2 = 2\\cos^2\\theta + 2\\sin^2\\theta","explanation":"The \\(\\pm 2\\sin\\theta\\cos\\theta\\) cancel; the squared terms double."},{"stepNumber":5,"description":"Apply the identity.","workingLatex":"x^2 + y^2 = 2","explanation":"\\(2(\\cos^2\\theta + \\sin^2\\theta) = 2\\): a circle of radius \\(\\sqrt 2\\)."}],"finalAnswer":"\\(x^2 + y^2 = 2\\)."}},
  {"id":"y2pe2-028","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 61","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = 3\\sin t + 4\\cos t,\\ y = 3\\sin t - 4\\cos t\\) to Cartesian form.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Combine the equations to isolate single functions.","workingLatex":"x + y = 6\\sin t,\\quad x - y = 8\\cos t","explanation":"Adding cancels the \\(\\cos t\\) terms; subtracting cancels the \\(\\sin t\\) terms."},{"stepNumber":2,"description":"Isolate \\(\\sin t\\).","workingLatex":"\\sin t = \\tfrac{x + y}{6}","explanation":"Divide \\(x + y = 6\\sin t\\) by 6."},{"stepNumber":3,"description":"Isolate \\(\\cos t\\).","workingLatex":"\\cos t = \\tfrac{x - y}{8}","explanation":"Divide \\(x - y = 8\\cos t\\) by 8."},{"stepNumber":4,"description":"Square and add.","workingLatex":"\\left(\\tfrac{x + y}{6}\\right)^2 + \\left(\\tfrac{x - y}{8}\\right)^2 = 1","explanation":"Apply \\(\\sin^2 t + \\cos^2 t = 1\\)."},{"stepNumber":5,"description":"State the curve.","workingLatex":"\\tfrac{(x + y)^2}{36} + \\tfrac{(x - y)^2}{64} = 1","explanation":"A rotated ellipse (its axes lie along \\(y = x\\) and \\(y = -x\\))."}],"finalAnswer":"\\(\\tfrac{(x + y)^2}{36} + \\tfrac{(x - y)^2}{64} = 1\\) (rotated ellipse)."}},
  {"id":"y2pe2-029","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 05","difficulty":"Foundation","questionText":"For the curve \\(x = 2\\cos\\theta,\\ y = 3\\sin\\theta\\), find the point at \\(\\theta = \\tfrac{\\pi}{2}\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Substitute \\(\\theta = \\tfrac{\\pi}{2}\\) into \\(x\\).","workingLatex":"x = 2\\cos\\tfrac{\\pi}{2} = 2 \\cdot 0 = 0","explanation":"\\(\\cos\\tfrac{\\pi}{2} = 0\\)."},{"stepNumber":2,"description":"Substitute into \\(y\\).","workingLatex":"y = 3\\sin\\tfrac{\\pi}{2} = 3 \\cdot 1 = 3","explanation":"\\(\\sin\\tfrac{\\pi}{2} = 1\\)."},{"stepNumber":3,"description":"State the point.","workingLatex":"(0, 3)","explanation":"The top of the ellipse, where the curve crosses the \\(y\\)-axis."}],"finalAnswer":"\\((0, 3)\\)."}},
  {"id":"y2pe2-030","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 06","difficulty":"Foundation","questionText":"Verify that the point \\((2, 0)\\) lies on the curve \\(x = 2\\cos\\theta,\\ y = 3\\sin\\theta\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Decide which equation pins down \\(\\theta\\).","workingLatex":"x = 2\\cos\\theta = 2 \\;\\Rightarrow\\; \\cos\\theta = 1","explanation":"For the \\(x\\)-coordinate to be 2 (its maximum), \\(\\cos\\theta\\) must be 1."},{"stepNumber":2,"description":"Solve for \\(\\theta\\).","workingLatex":"\\theta = 0","explanation":"\\(\\cos\\theta = 1\\) at \\(\\theta = 0\\)."},{"stepNumber":3,"description":"Check \\(y\\) at that \\(\\theta\\).","workingLatex":"y = 3\\sin 0 = 0","explanation":"At \\(\\theta = 0\\), \\(y = 0\\), matching the required \\(y\\)-coordinate."},{"stepNumber":4,"description":"Conclude.","workingLatex":"(2, 0)\\ \\text{lies on the curve}","explanation":"Both coordinates come from \\(\\theta = 0\\), so the point is on the curve."}],"finalAnswer":"Yes, at \\(\\theta = 0\\)."}},
  {"id":"y2pe2-031","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 34","difficulty":"Standard","questionText":"Convert the parametric equations \\(x = \\tan t,\\ y = \\sec t\\) to Cartesian form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"Here \\(y = \\sec t\\) and \\(x = \\tan t\\), so the sec–tan identity applies."},{"stepNumber":2,"description":"Square each.","workingLatex":"y^2 = \\sec^2 t,\\quad x^2 = \\tan^2 t","explanation":"Square the isolated functions."},{"stepNumber":3,"description":"Subtract (sec² minus tan²).","workingLatex":"y^2 - x^2 = \\sec^2 t - \\tan^2 t = 1","explanation":"Put the \\(\\sec^2\\) term first since it carries the \\(+1\\)."},{"stepNumber":4,"description":"State the curve.","workingLatex":"y^2 - x^2 = 1","explanation":"A hyperbola opening up–down."}],"finalAnswer":"\\(y^2 - x^2 = 1\\)."}},
  {"id":"y2pe2-032","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 35","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 2\\tan t,\\ y = 3\\sec t\\). Find its Cartesian form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"Sec and tan present."},{"stepNumber":2,"description":"Isolate \\(\\tan t\\) and \\(\\sec t\\).","workingLatex":"\\tan t = \\tfrac{x}{2},\\quad \\sec t = \\tfrac{y}{3}","explanation":"Divide each by its coefficient."},{"stepNumber":3,"description":"Square each.","workingLatex":"\\tan^2 t = \\tfrac{x^2}{4},\\quad \\sec^2 t = \\tfrac{y^2}{9}","explanation":"Square the isolated functions."},{"stepNumber":4,"description":"Subtract (sec² minus tan²).","workingLatex":"\\tfrac{y^2}{9} - \\tfrac{x^2}{4} = 1","explanation":"The \\(\\sec^2\\) term leads, giving the \\(+1\\)."},{"stepNumber":5,"description":"State the curve.","workingLatex":"\\tfrac{y^2}{9} - \\tfrac{x^2}{4} = 1","explanation":"A hyperbola opening vertically."}],"finalAnswer":"\\(\\tfrac{y^2}{9} - \\tfrac{x^2}{4} = 1\\)."}},
  {"id":"y2pe2-033","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 36","difficulty":"Standard","questionText":"Convert the parametric equations \\(x = \\cot t,\\ y = \\csc t\\) to Cartesian form.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\csc^2 t - \\cot^2 t = 1","explanation":"With \\(y = \\csc t\\) and \\(x = \\cot t\\), use \\(\\csc^2 - \\cot^2 = 1\\)."},{"stepNumber":2,"description":"Square each.","workingLatex":"y^2 = \\csc^2 t,\\quad x^2 = \\cot^2 t","explanation":"Square the isolated functions."},{"stepNumber":3,"description":"Subtract.","workingLatex":"y^2 - x^2 = \\csc^2 t - \\cot^2 t = 1","explanation":"Csc² carries the \\(+1\\)."},{"stepNumber":4,"description":"State the curve.","workingLatex":"y^2 - x^2 = 1","explanation":"A hyperbola opening vertically."}],"finalAnswer":"\\(y^2 - x^2 = 1\\)."}},
  {"id":"y2pe2-034","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 07","difficulty":"Foundation","questionText":"Convert \\(x = 3\\sin t,\\ y = 4\\cos t\\) to Cartesian form and identify the conic.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\sin^2 t + \\cos^2 t = 1","explanation":"Isolate \\(\\sin t,\\cos t\\), then use the Pythagorean identity."},{"stepNumber":2,"description":"Isolate \\(\\sin t\\) and \\(\\cos t\\).","workingLatex":"\\sin t = \\tfrac{x}{3},\\quad \\cos t = \\tfrac{y}{4}","explanation":"Divide each by its amplitude."},{"stepNumber":3,"description":"Square and add.","workingLatex":"\\tfrac{x^2}{9} + \\tfrac{y^2}{16} = \\sin^2 t + \\cos^2 t = 1","explanation":"Apply the identity."},{"stepNumber":4,"description":"Identify the conic.","workingLatex":"\\text{ellipse, semi-axes } 3 \\text{ and } 4","explanation":"Two positive squared terms summing to 1 — an ellipse, not a circle (the denominators differ)."}],"finalAnswer":"\\(\\tfrac{x^2}{9} + \\tfrac{y^2}{16} = 1\\) — ellipse."}},
  {"id":"y2pe2-035","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 08","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = 2\\sec t,\\ y = 3\\tan t\\). Identify the conic and give its Cartesian equation.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"Sec and tan ⇒ sec–tan identity ⇒ a difference of squares ⇒ a hyperbola."},{"stepNumber":2,"description":"Isolate \\(\\sec t\\) and \\(\\tan t\\).","workingLatex":"\\sec t = \\tfrac{x}{2},\\quad \\tan t = \\tfrac{y}{3}","explanation":"Divide each by its coefficient."},{"stepNumber":3,"description":"Square and subtract.","workingLatex":"\\tfrac{x^2}{4} - \\tfrac{y^2}{9} = 1","explanation":"Apply the identity."},{"stepNumber":4,"description":"Identify the conic.","workingLatex":"\\text{hyperbola}","explanation":"The minus sign between the squared terms makes this a hyperbola."}],"finalAnswer":"Hyperbola \\(\\tfrac{x^2}{4} - \\tfrac{y^2}{9} = 1\\)."}},
  {"id":"y2pe2-036","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 62","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = \\tfrac{1}{2}\\sin 2\\theta,\\ y = \\cos 2\\theta\\) to Cartesian form.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Express \\(\\sin 2\\theta\\) via \\(x\\).","workingLatex":"\\sin 2\\theta = 2x","explanation":"From \\(x = \\tfrac12\\sin 2\\theta\\), multiply by 2."},{"stepNumber":2,"description":"Note \\(\\cos 2\\theta = y\\).","workingLatex":"\\cos 2\\theta = y","explanation":"The second equation is already isolated."},{"stepNumber":3,"description":"Use the identity with argument \\(2\\theta\\).","workingLatex":"\\sin^2 2\\theta + \\cos^2 2\\theta = 1","explanation":"The Pythagorean identity holds for any angle, here \\(2\\theta\\)."},{"stepNumber":4,"description":"Substitute and simplify.","workingLatex":"(2x)^2 + y^2 = 1 \\;\\Rightarrow\\; 4x^2 + y^2 = 1","explanation":"Replace \\(\\sin 2\\theta = 2x\\), \\(\\cos 2\\theta = y\\). An ellipse."}],"finalAnswer":"\\(4x^2 + y^2 = 1\\)."}},
  {"id":"y2pe2-037","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 37","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 2\\cos^2 t,\\ y = 3\\sin^2 t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Isolate \\(\\cos^2 t\\) and \\(\\sin^2 t\\).","workingLatex":"\\cos^2 t = \\tfrac{x}{2},\\quad \\sin^2 t = \\tfrac{y}{3}","explanation":"Divide each equation by its coefficient — the squared trig functions are already present."},{"stepNumber":2,"description":"Add the two.","workingLatex":"\\tfrac{x}{2} + \\tfrac{y}{3} = \\cos^2 t + \\sin^2 t","explanation":"Adding builds the Pythagorean identity directly."},{"stepNumber":3,"description":"Apply the identity.","workingLatex":"\\tfrac{x}{2} + \\tfrac{y}{3} = 1","explanation":"\\(\\cos^2 t + \\sin^2 t = 1\\)."},{"stepNumber":4,"description":"Clear fractions.","workingLatex":"3x + 2y = 6","explanation":"Multiply by 6 — a line, but only the segment with \\(x, y \\ge 0\\) is traced."}],"finalAnswer":"\\(3x + 2y = 6\\) (line segment in first quadrant)."}},
  {"id":"y2pe2-038","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 63","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = 2\\sin^2 t,\\ y = \\sin 2t\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Relate \\(x\\) to \\(\\sin^2 t\\).","workingLatex":"\\sin^2 t = \\tfrac{x}{2}","explanation":"From \\(x = 2\\sin^2 t\\)."},{"stepNumber":2,"description":"Get \\(\\cos^2 t\\) too.","workingLatex":"\\cos^2 t = 1 - \\sin^2 t = 1 - \\tfrac{x}{2}","explanation":"Use \\(\\sin^2 + \\cos^2 = 1\\)."},{"stepNumber":3,"description":"Expand and square \\(y = \\sin 2t\\).","workingLatex":"y^2 = (2\\sin t\\cos t)^2 = 4\\sin^2 t\\cos^2 t","explanation":"Square the product form so only \\(\\sin^2 t,\\cos^2 t\\) appear."},{"stepNumber":4,"description":"Substitute.","workingLatex":"y^2 = 4 \\cdot \\tfrac{x}{2}\\left(1 - \\tfrac{x}{2}\\right) = 2x - x^2","explanation":"Put in the expressions for \\(\\sin^2 t\\) and \\(\\cos^2 t\\) and simplify."},{"stepNumber":5,"description":"Complete the square.","workingLatex":"(x - 1)^2 + y^2 = 1","explanation":"\\(y^2 = 2x - x^2 \\Rightarrow x^2 - 2x + y^2 = 0 \\Rightarrow (x-1)^2 + y^2 = 1\\): a circle, centre \\((1,0)\\), radius 1."}],"finalAnswer":"\\(y^2 = 2x - x^2\\), i.e. \\((x - 1)^2 + y^2 = 1\\)."}},
  {"id":"y2pe2-039","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 38","difficulty":"Standard","questionText":"Show that the curve \\(x = \\tan t,\\ y = \\sin 2t\\) has Cartesian equation \\(y = \\tfrac{2x}{1 + x^2}\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Recall the \\(t\\)-formula for \\(\\sin 2t\\).","workingLatex":"\\sin 2t = \\tfrac{2\\tan t}{1 + \\tan^2 t}","explanation":"This standard identity rewrites \\(\\sin 2t\\) purely through \\(\\tan t\\)."},{"stepNumber":2,"description":"Substitute \\(x = \\tan t\\).","workingLatex":"y = \\tfrac{2x}{1 + x^2}","explanation":"Replace \\(\\tan t\\) by \\(x\\), confirming the stated equation."},{"stepNumber":3,"description":"Conclude.","workingLatex":"y = \\tfrac{2x}{1 + x^2}\\ \\checkmark","explanation":"The Cartesian equation matches the one to be shown."}],"finalAnswer":"\\(y = \\tfrac{2x}{1 + x^2}\\)."}},
  {"id":"y2pe2-040","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 39","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 1 - \\cos t,\\ y = \\sin t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"Isolate each trig function, then use the identity."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\).","workingLatex":"\\cos t = 1 - x","explanation":"From \\(x = 1 - \\cos t\\), rearrange for \\(\\cos t\\)."},{"stepNumber":3,"description":"Note \\(\\sin t = y\\).","workingLatex":"\\sin t = y","explanation":"The second equation is already isolated."},{"stepNumber":4,"description":"Square and add.","workingLatex":"(1 - x)^2 + y^2 = 1","explanation":"Apply the identity to \\(\\cos t = 1 - x\\) and \\(\\sin t = y\\)."},{"stepNumber":5,"description":"Tidy.","workingLatex":"(x - 1)^2 + y^2 = 1","explanation":"\\((1 - x)^2 = (x - 1)^2\\): a circle, centre \\((1, 0)\\), radius 1."}],"finalAnswer":"\\((x - 1)^2 + y^2 = 1\\)."}},
  {"id":"y2pe2-041","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 40","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 1 + \\cos t,\\ y = 3 + \\sin t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"A unit-radius circle shifted to a new centre."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\) and \\(\\sin t\\).","workingLatex":"\\cos t = x - 1,\\quad \\sin t = y - 3","explanation":"Subtract the centre coordinates."},{"stepNumber":3,"description":"Square and add.","workingLatex":"(x - 1)^2 + (y - 3)^2 = \\cos^2 t + \\sin^2 t = 1","explanation":"Apply the identity — a circle of radius 1 centred at \\((1, 3)\\)."}],"finalAnswer":"\\((x - 1)^2 + (y - 3)^2 = 1\\)."}},
  {"id":"y2pe2-042","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 41","difficulty":"Standard","questionText":"Show that the curve \\(x = -1 + 2\\cos t,\\ y = 3 + 2\\sin t\\) is a circle, and state its centre and radius.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"To prove it is a circle, eliminate \\(t\\) and look for the form \\((x-a)^2 + (y-b)^2 = r^2\\)."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\) and \\(\\sin t\\).","workingLatex":"\\cos t = \\tfrac{x + 1}{2},\\quad \\sin t = \\tfrac{y - 3}{2}","explanation":"Subtract the centre and divide by 2."},{"stepNumber":3,"description":"Square and add.","workingLatex":"\\left(\\tfrac{x + 1}{2}\\right)^2 + \\left(\\tfrac{y - 3}{2}\\right)^2 = 1","explanation":"Apply the identity."},{"stepNumber":4,"description":"Clear denominators.","workingLatex":"(x + 1)^2 + (y - 3)^2 = 4","explanation":"Multiply by 4 — exactly the circle form."},{"stepNumber":5,"description":"Read off centre and radius.","workingLatex":"\\text{centre } (-1, 3),\\ r = 2","explanation":"Comparing with \\((x-a)^2 + (y-b)^2 = r^2\\)."}],"finalAnswer":"Circle centre \\((-1, 3)\\), radius 2."}},
  {"id":"y2pe2-043","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 09","difficulty":"Foundation","questionText":"State the range of \\(x\\) for the curve \\(x = 2\\cos t + 3\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Bound the cosine.","workingLatex":"-1 \\le \\cos t \\le 1","explanation":"Cosine never leaves \\([-1, 1]\\)."},{"stepNumber":2,"description":"Scale by 2.","workingLatex":"-2 \\le 2\\cos t \\le 2","explanation":"Multiply every part by the positive number 2."},{"stepNumber":3,"description":"Shift by 3.","workingLatex":"1 \\le 2\\cos t + 3 \\le 5","explanation":"Add 3 to every part; so \\(1 \\le x \\le 5\\)."}],"finalAnswer":"\\(1 \\le x \\le 5\\)."}},
  {"id":"y2pe2-044","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 10","difficulty":"Foundation","questionText":"State the range of \\(y\\) for the curve \\(y = 3\\sin t - 1\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Bound the sine.","workingLatex":"-1 \\le \\sin t \\le 1","explanation":"Sine never leaves \\([-1, 1]\\)."},{"stepNumber":2,"description":"Scale by 3.","workingLatex":"-3 \\le 3\\sin t \\le 3","explanation":"Multiply every part by 3."},{"stepNumber":3,"description":"Shift by \\(-1\\).","workingLatex":"-4 \\le 3\\sin t - 1 \\le 2","explanation":"Subtract 1 from every part; so \\(-4 \\le y \\le 2\\)."}],"finalAnswer":"\\(-4 \\le y \\le 2\\)."}},
  {"id":"y2pe2-045","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 64","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = \\cos\\theta,\\ y = \\sin 3\\theta\\). Find its Cartesian equation.","marks":5,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Expand the triple angle.","workingLatex":"\\sin 3\\theta = 3\\sin\\theta - 4\\sin^3\\theta","explanation":"Use the triple-angle expansion so \\(y\\) is in powers of \\(\\sin\\theta\\)."},{"stepNumber":2,"description":"Express \\(\\sin\\theta\\) via \\(x\\).","workingLatex":"\\sin\\theta = \\pm\\sqrt{1 - x^2}","explanation":"From \\(\\cos^2\\theta + \\sin^2\\theta = 1\\) with \\(\\cos\\theta = x\\); both signs occur."},{"stepNumber":3,"description":"Substitute.","workingLatex":"y = 3\\sin\\theta - 4\\sin^3\\theta = \\pm\\!\\left[3\\sqrt{1 - x^2} - 4(1 - x^2)^{3/2}\\right]","explanation":"Replace \\(\\sin\\theta\\); \\(\\sin^3\\theta = (\\pm\\sqrt{1-x^2})^3 = \\pm(1-x^2)^{3/2}\\)."},{"stepNumber":4,"description":"State the curve.","workingLatex":"y = \\pm\\!\\left[3\\sqrt{1 - x^2} - 4(1 - x^2)^{3/2}\\right]","explanation":"The \\(\\pm\\) gives the upper and lower halves."}],"finalAnswer":"\\(y = \\pm[3\\sqrt{1 - x^2} - 4(1 - x^2)^{3/2}]\\)."}},
  {"id":"y2pe2-046","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 65","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = \\cos\\theta,\\ y = \\cos\\theta + \\sin\\theta\\). Find its Cartesian equation.","marks":5,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Make \\(\\sin\\theta\\) the subject.","workingLatex":"\\sin\\theta = y - x","explanation":"Subtract \\(x = \\cos\\theta\\) from \\(y = \\cos\\theta + \\sin\\theta\\)."},{"stepNumber":2,"description":"List the isolated functions.","workingLatex":"\\cos\\theta = x,\\quad \\sin\\theta = y - x","explanation":"Both trig functions are now expressed in \\(x, y\\)."},{"stepNumber":3,"description":"Apply \\(\\cos^2\\theta + \\sin^2\\theta = 1\\).","workingLatex":"x^2 + (y - x)^2 = 1","explanation":"Substitute into the Pythagorean identity."},{"stepNumber":4,"description":"Expand and collect.","workingLatex":"x^2 + y^2 - 2xy + x^2 = 1 \\;\\Rightarrow\\; 2x^2 - 2xy + y^2 = 1","explanation":"Expand \\((y - x)^2\\) and combine the two \\(x^2\\) terms — a rotated ellipse."}],"finalAnswer":"\\(2x^2 - 2xy + y^2 = 1\\)."}},
  {"id":"y2pe2-047","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 66","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = \\sin\\theta,\\ y = \\tan\\theta\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Write \\(\\tan\\theta\\) as a ratio.","workingLatex":"y = \\tan\\theta = \\tfrac{\\sin\\theta}{\\cos\\theta}","explanation":"Express \\(\\tan\\theta\\) so the known \\(\\sin\\theta = x\\) can be used."},{"stepNumber":2,"description":"Express \\(\\cos\\theta\\) via \\(x\\).","workingLatex":"\\cos\\theta = \\pm\\sqrt{1 - x^2}","explanation":"From \\(\\sin^2\\theta + \\cos^2\\theta = 1\\) with \\(\\sin\\theta = x\\)."},{"stepNumber":3,"description":"Substitute.","workingLatex":"y = \\tfrac{x}{\\pm\\sqrt{1 - x^2}}","explanation":"Put \\(\\sin\\theta = x\\) and \\(\\cos\\theta = \\pm\\sqrt{1 - x^2}\\)."},{"stepNumber":4,"description":"Square to remove the \\(\\pm\\) and the surd.","workingLatex":"y^2(1 - x^2) = x^2,\\ \\text{i.e.}\\ y^2 = \\tfrac{x^2}{1 - x^2}","explanation":"Squaring clears both the sign and the square root."}],"finalAnswer":"\\(y^2(1 - x^2) = x^2\\), i.e. \\(y^2 = \\tfrac{x^2}{1 - x^2}\\)."}},
  {"id":"y2pe2-048","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 42","difficulty":"Standard","questionText":"Show that the ellipse \\(x = a\\cos\\theta,\\ y = b\\sin\\theta\\) has Cartesian equation \\(\\tfrac{x^2}{a^2} + \\tfrac{y^2}{b^2} = 1\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2\\theta + \\sin^2\\theta = 1","explanation":"Work with general \\(a, b\\): isolate the trig functions, then use the identity."},{"stepNumber":2,"description":"Isolate \\(\\cos\\theta\\) and \\(\\sin\\theta\\).","workingLatex":"\\cos\\theta = \\tfrac{x}{a},\\quad \\sin\\theta = \\tfrac{y}{b}","explanation":"Divide by the respective semi-axis."},{"stepNumber":3,"description":"Square and add.","workingLatex":"\\tfrac{x^2}{a^2} + \\tfrac{y^2}{b^2} = \\cos^2\\theta + \\sin^2\\theta","explanation":"Square each and add."},{"stepNumber":4,"description":"Apply the identity.","workingLatex":"\\tfrac{x^2}{a^2} + \\tfrac{y^2}{b^2} = 1","explanation":"The standard ellipse equation, as required."}],"finalAnswer":"\\(\\tfrac{x^2}{a^2} + \\tfrac{y^2}{b^2} = 1\\)."}},
  {"id":"y2pe2-049","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 67","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = \\sin t,\\ y = \\cos 3t\\). Find its Cartesian equation.","marks":5,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Expand the triple angle.","workingLatex":"\\cos 3t = 4\\cos^3 t - 3\\cos t","explanation":"Use the triple-angle expansion so \\(y\\) is in powers of \\(\\cos t\\)."},{"stepNumber":2,"description":"Express \\(\\cos t\\) via \\(x\\).","workingLatex":"\\cos t = \\pm\\sqrt{1 - x^2}","explanation":"From \\(\\sin^2 t + \\cos^2 t = 1\\) with \\(\\sin t = x\\)."},{"stepNumber":3,"description":"Substitute.","workingLatex":"y = 4\\cos^3 t - 3\\cos t = \\pm\\!\\left[4(1 - x^2)^{3/2} - 3\\sqrt{1 - x^2}\\right]","explanation":"Replace \\(\\cos t\\); \\(\\cos^3 t = \\pm(1 - x^2)^{3/2}\\)."},{"stepNumber":4,"description":"State the curve.","workingLatex":"y = \\pm\\!\\left[4(1 - x^2)^{3/2} - 3\\sqrt{1 - x^2}\\right]","explanation":"The \\(\\pm\\) covers both halves."}],"finalAnswer":"\\(y = \\pm[4(1 - x^2)^{3/2} - 3\\sqrt{1 - x^2}]\\)."}},
  {"id":"y2pe2-050","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 11","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = \\sin 2t,\\ y = \\cos 2t\\). Find its Cartesian equation.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\sin^2 2t + \\cos^2 2t = 1","explanation":"The identity holds for any argument; here both functions use \\(2t\\)."},{"stepNumber":2,"description":"Square and add.","workingLatex":"x^2 + y^2 = \\sin^2 2t + \\cos^2 2t","explanation":"Square \\(x = \\sin 2t\\) and \\(y = \\cos 2t\\), then add."},{"stepNumber":3,"description":"Apply the identity.","workingLatex":"x^2 + y^2 = 1","explanation":"The unit circle (traced twice over \\(0 \\le t < 2\\pi\\))."}],"finalAnswer":"\\(x^2 + y^2 = 1\\)."}},
  {"id":"y2pe2-051","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 43","difficulty":"Standard","questionText":"For the curve \\(x = 2\\cos t,\\ y = \\sin t\\), find the \\(y\\)-values when \\(x = 1\\).","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Use \\(x = 1\\) to find \\(\\cos t\\).","workingLatex":"1 = 2\\cos t \\;\\Rightarrow\\; \\cos t = \\tfrac{1}{2}","explanation":"Set the \\(x\\)-equation equal to 1 and solve for \\(\\cos t\\)."},{"stepNumber":2,"description":"Find \\(\\sin t\\) from the identity.","workingLatex":"\\sin^2 t = 1 - \\cos^2 t = 1 - \\tfrac14 = \\tfrac34","explanation":"Use \\(\\sin^2 t + \\cos^2 t = 1\\)."},{"stepNumber":3,"description":"Take the square root.","workingLatex":"\\sin t = \\pm\\tfrac{\\sqrt 3}{2}","explanation":"Both signs are valid — the line \\(x = 1\\) meets the curve at two points."},{"stepNumber":4,"description":"State the \\(y\\)-values.","workingLatex":"y = \\pm\\tfrac{\\sqrt 3}{2}","explanation":"Since \\(y = \\sin t\\)."}],"finalAnswer":"\\(y = \\pm\\tfrac{\\sqrt 3}{2}\\)."}},
  {"id":"y2pe2-052","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 44","difficulty":"Standard","questionText":"Find the range of \\(x = \\cos\\theta + \\sin\\theta\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Combine into a single sinusoid.","workingLatex":"x = \\cos\\theta + \\sin\\theta = R\\sin(\\theta + \\alpha)","explanation":"A sum \\(a\\sin\\theta + b\\cos\\theta\\) collapses to one sine wave of amplitude \\(R = \\sqrt{a^2 + b^2}\\)."},{"stepNumber":2,"description":"Compute the amplitude.","workingLatex":"R = \\sqrt{1^2 + 1^2} = \\sqrt 2","explanation":"Both coefficients are 1, so \\(R = \\sqrt 2\\) (here \\(\\alpha = \\tfrac{\\pi}{4}\\))."},{"stepNumber":3,"description":"Use the range of sine.","workingLatex":"-1 \\le \\sin(\\theta + \\alpha) \\le 1 \\;\\Rightarrow\\; -\\sqrt 2 \\le x \\le \\sqrt 2","explanation":"Multiply the sine bounds by the amplitude \\(\\sqrt 2\\)."}],"finalAnswer":"\\(-\\sqrt 2 \\le x \\le \\sqrt 2\\)."}},
  {"id":"y2pe2-053","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 12","difficulty":"Foundation","questionText":"For the curve \\(x = \\sin\\theta + \\cos\\theta,\\ y = \\sin\\theta - \\cos\\theta\\), find \\(x^2 + y^2\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set up \\(x^2 + y^2\\).","workingLatex":"x^2 + y^2 = (\\sin\\theta + \\cos\\theta)^2 + (\\sin\\theta - \\cos\\theta)^2","explanation":"Write out both squares; the cross terms will cancel."},{"stepNumber":2,"description":"Expand both squares.","workingLatex":"= (\\sin^2\\theta + 2\\sin\\theta\\cos\\theta + \\cos^2\\theta) + (\\sin^2\\theta - 2\\sin\\theta\\cos\\theta + \\cos^2\\theta)","explanation":"The \\(+2\\sin\\theta\\cos\\theta\\) and \\(-2\\sin\\theta\\cos\\theta\\) are about to cancel."},{"stepNumber":3,"description":"Simplify.","workingLatex":"= 2(\\sin^2\\theta + \\cos^2\\theta) = 2","explanation":"Cross terms cancel; the identity makes the rest 2. (So the curve is a circle of radius \\(\\sqrt 2\\).)"}],"finalAnswer":"2."}},
  {"id":"y2pe2-054","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 45","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = \\cos 2t,\\ y = \\sin 2t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 2t + \\sin^2 2t = 1","explanation":"The identity works with argument \\(2t\\)."},{"stepNumber":2,"description":"Square and add.","workingLatex":"x^2 + y^2 = \\cos^2 2t + \\sin^2 2t","explanation":"Square \\(x = \\cos 2t\\) and \\(y = \\sin 2t\\), then add."},{"stepNumber":3,"description":"Apply the identity.","workingLatex":"x^2 + y^2 = 1","explanation":"The unit circle."}],"finalAnswer":"\\(x^2 + y^2 = 1\\)."}},
  {"id":"y2pe2-055","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 13","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = \\sec^2 t,\\ y = \\tan^2 t\\). Find its Cartesian equation.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Spot the direct identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"Here \\(x = \\sec^2 t\\) and \\(y = \\tan^2 t\\) are already the squared functions — no squaring needed."},{"stepNumber":2,"description":"Subtract the equations.","workingLatex":"x - y = \\sec^2 t - \\tan^2 t","explanation":"Subtracting builds the identity directly."},{"stepNumber":3,"description":"Apply the identity.","workingLatex":"x - y = 1","explanation":"A straight line; only the part with \\(x \\ge 1,\\ y \\ge 0\\) is traced."}],"finalAnswer":"\\(x - y = 1\\) (i.e. straight line)."}},
  {"id":"y2pe2-056","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 46","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = \\sin 2t,\\ y = \\cos 2t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\sin^2 2t + \\cos^2 2t = 1","explanation":"The identity holds for argument \\(2t\\)."},{"stepNumber":2,"description":"Square and add.","workingLatex":"x^2 + y^2 = \\sin^2 2t + \\cos^2 2t","explanation":"Square \\(x = \\sin 2t\\) and \\(y = \\cos 2t\\), then add."},{"stepNumber":3,"description":"Apply the identity.","workingLatex":"x^2 + y^2 = 1","explanation":"The unit circle."}],"finalAnswer":"\\(x^2 + y^2 = 1\\)."}},
  {"id":"y2pe2-057","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 47","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 5 + 3\\cos t,\\ y = 2 + 4\\sin t\\). Describe the curve fully.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric","ellipse"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"A shifted ellipse: subtract the centre, divide by the semi-axes."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\).","workingLatex":"\\cos t = \\tfrac{x - 5}{3}","explanation":"From \\(x = 5 + 3\\cos t\\)."},{"stepNumber":3,"description":"Isolate \\(\\sin t\\).","workingLatex":"\\sin t = \\tfrac{y - 2}{4}","explanation":"From \\(y = 2 + 4\\sin t\\)."},{"stepNumber":4,"description":"Square and add.","workingLatex":"\\tfrac{(x - 5)^2}{9} + \\tfrac{(y - 2)^2}{16} = 1","explanation":"Apply the identity."},{"stepNumber":5,"description":"Describe the curve.","workingLatex":"\\text{ellipse: centre } (5, 2),\\ \\text{semi-axes } 3 \\text{ and } 4","explanation":"Horizontal semi-axis 3, vertical semi-axis 4."}],"finalAnswer":"Ellipse centre \\((5, 2)\\), semi-axes 3 and 4."}},
  {"id":"y2pe2-058","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 68","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = 3 + 2\\tan t,\\ y = -1 + 4\\sec t\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"Sec and tan ⇒ a hyperbola; subtract the centre and scale first."},{"stepNumber":2,"description":"Isolate \\(\\tan t\\).","workingLatex":"\\tan t = \\tfrac{x - 3}{2}","explanation":"From \\(x = 3 + 2\\tan t\\)."},{"stepNumber":3,"description":"Isolate \\(\\sec t\\).","workingLatex":"\\sec t = \\tfrac{y + 1}{4}","explanation":"From \\(y = -1 + 4\\sec t\\)."},{"stepNumber":4,"description":"Square and subtract (sec² first).","workingLatex":"\\tfrac{(y + 1)^2}{16} - \\tfrac{(x - 3)^2}{4} = 1","explanation":"The \\(\\sec^2\\) term carries the \\(+1\\)."},{"stepNumber":5,"description":"Identify.","workingLatex":"\\text{hyperbola, centre } (3, -1)","explanation":"Opens vertically since the \\(y\\)-term is positive."}],"finalAnswer":"Hyperbola."}},
  {"id":"y2pe2-059","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 14","difficulty":"Foundation","questionText":"State the range of \\(x\\) for the curve \\(x = \\sin^2\\theta\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Bound \\(\\sin\\theta\\).","workingLatex":"-1 \\le \\sin\\theta \\le 1","explanation":"Sine lies in \\([-1, 1]\\)."},{"stepNumber":2,"description":"Square it.","workingLatex":"0 \\le \\sin^2\\theta \\le 1","explanation":"Squaring sends \\([-1, 1]\\) onto \\([0, 1]\\) (the minimum 0 occurs at \\(\\sin\\theta = 0\\))."},{"stepNumber":3,"description":"State the range.","workingLatex":"0 \\le x \\le 1","explanation":"Since \\(x = \\sin^2\\theta\\)."}],"finalAnswer":"\\(0 \\le x \\le 1\\)."}},
  {"id":"y2pe2-060","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 69","difficulty":"Challenge","questionText":"Convert the parametric equations \\(x = \\cos^3 t,\\ y = \\sin^3 t\\) to Cartesian form.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Isolate the trig functions by cube-rooting.","workingLatex":"x^{1/3} = \\cos t,\\quad y^{1/3} = \\sin t","explanation":"Take cube roots so a single \\(\\cos t,\\sin t\\) appears, ready for the identity."},{"stepNumber":2,"description":"Square each.","workingLatex":"x^{2/3} = \\cos^2 t,\\quad y^{2/3} = \\sin^2 t","explanation":"\\((x^{1/3})^2 = x^{2/3}\\)."},{"stepNumber":3,"description":"Add and apply the identity.","workingLatex":"x^{2/3} + y^{2/3} = \\cos^2 t + \\sin^2 t = 1","explanation":"The astroid."}],"finalAnswer":"\\(x^{2/3} + y^{2/3} = 1\\) (astroid)."}},
  {"id":"y2pe2-061","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 15","difficulty":"Foundation","questionText":"Verify that the point \\((0, 1)\\) lies on the astroid \\(x = \\cos^3 t,\\ y = \\sin^3 t\\).","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose a convenient \\(t\\).","workingLatex":"t = \\tfrac{\\pi}{2}","explanation":"Pick the angle that makes \\(\\cos\\) or \\(\\sin\\) equal to 0 or 1."},{"stepNumber":2,"description":"Evaluate the coordinates.","workingLatex":"x = \\cos^3\\tfrac{\\pi}{2} = 0,\\quad y = \\sin^3\\tfrac{\\pi}{2} = 1","explanation":"\\(\\cos\\tfrac{\\pi}{2} = 0\\) and \\(\\sin\\tfrac{\\pi}{2} = 1\\), so the curve passes through \\((0, 1)\\)."},{"stepNumber":3,"description":"Confirm with the Cartesian form.","workingLatex":"0^{2/3} + 1^{2/3} = 0 + 1 = 1\\ \\checkmark","explanation":"The point also satisfies \\(x^{2/3} + y^{2/3} = 1\\)."}],"finalAnswer":"\\(0 + 1 = 1\\) ✓."}},
  {"id":"y2pe2-062","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 16","difficulty":"Foundation","questionText":"For the curve \\(x = 5\\sin t,\\ y = 1 + \\cos t\\), find the point at \\(t = \\tfrac{\\pi}{2}\\).","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Substitute \\(t = \\tfrac{\\pi}{2}\\) into \\(x\\).","workingLatex":"x = 5\\sin\\tfrac{\\pi}{2} = 5 \\cdot 1 = 5","explanation":"\\(\\sin\\tfrac{\\pi}{2} = 1\\)."},{"stepNumber":2,"description":"Substitute into \\(y\\).","workingLatex":"y = 1 + \\cos\\tfrac{\\pi}{2} = 1 + 0 = 1","explanation":"\\(\\cos\\tfrac{\\pi}{2} = 0\\)."},{"stepNumber":3,"description":"State the point.","workingLatex":"(5, 1)","explanation":"Both coordinates come from \\(t = \\tfrac{\\pi}{2}\\)."}],"finalAnswer":"\\((5, 1)\\)."}},
  {"id":"y2pe2-063","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 48","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = 4\\cos t,\\ y = 3\\sin t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"Isolate the trig functions, then use the identity."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\) and \\(\\sin t\\).","workingLatex":"\\cos t = \\tfrac{x}{4},\\quad \\sin t = \\tfrac{y}{3}","explanation":"Divide by the amplitudes 4 and 3."},{"stepNumber":3,"description":"Square and add.","workingLatex":"\\tfrac{x^2}{16} + \\tfrac{y^2}{9} = \\cos^2 t + \\sin^2 t = 1","explanation":"Apply the identity — an ellipse with semi-axes 4 and 3."}],"finalAnswer":"\\(\\tfrac{x^2}{16} + \\tfrac{y^2}{9} = 1\\)."}},
  {"id":"y2pe2-064","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 17","difficulty":"Foundation","questionText":"For \\(x = \\cos t,\\ y = \\sin t\\), what is the smallest positive period that traces the full unit circle exactly once?","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Note the period of the components.","workingLatex":"\\cos t,\\ \\sin t\\ \\text{repeat every } 2\\pi","explanation":"Both standard trig functions have period \\(2\\pi\\)."},{"stepNumber":2,"description":"State the smallest period.","workingLatex":"2\\pi","explanation":"Over \\(0 \\le t < 2\\pi\\) the point \\((\\cos t, \\sin t)\\) traces the whole unit circle exactly once."}],"finalAnswer":"\\(2\\pi\\)."}},
  {"id":"y2pe2-065","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 18","difficulty":"Foundation","questionText":"For \\(x = \\cos 2t,\\ y = \\sin 2t\\), what is the smallest positive period?","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Find the period of \\(\\cos 2t\\) and \\(\\sin 2t\\).","workingLatex":"\\text{period} = \\tfrac{2\\pi}{2}","explanation":"A factor of 2 inside the function divides the period by 2."},{"stepNumber":2,"description":"State the period.","workingLatex":"\\pi","explanation":"So the unit circle is traced once over \\(0 \\le t < \\pi\\) (and twice over a full \\(2\\pi\\))."}],"finalAnswer":"\\(\\pi\\)."}},
  {"id":"y2pe2-066","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 19","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = \\sin t,\\ y = \\cos t\\). Find its Cartesian equation.","marks":1,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\sin^2 t + \\cos^2 t = 1","explanation":"\\(x = \\sin t,\\ y = \\cos t\\) are already isolated."},{"stepNumber":2,"description":"Square and add.","workingLatex":"x^2 + y^2 = \\sin^2 t + \\cos^2 t","explanation":"Square each and add."},{"stepNumber":3,"description":"Apply the identity.","workingLatex":"x^2 + y^2 = 1","explanation":"The unit circle."}],"finalAnswer":"\\(x^2 + y^2 = 1\\)."}},
  {"id":"y2pe2-067","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 70","difficulty":"Challenge","questionText":"A curve has parametric equations \\(x = 1 + \\tan t,\\ y = -3 + 2\\sec t\\). Find its Cartesian equation.","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"Sec and tan ⇒ sec–tan identity."},{"stepNumber":2,"description":"Isolate \\(\\tan t\\).","workingLatex":"\\tan t = x - 1","explanation":"From \\(x = 1 + \\tan t\\)."},{"stepNumber":3,"description":"Isolate \\(\\sec t\\).","workingLatex":"\\sec t = \\tfrac{y + 3}{2}","explanation":"From \\(y = -3 + 2\\sec t\\)."},{"stepNumber":4,"description":"Square and subtract (sec² first).","workingLatex":"\\left(\\tfrac{y + 3}{2}\\right)^2 - (x - 1)^2 = 1","explanation":"The \\(\\sec^2\\) term carries the \\(+1\\)."},{"stepNumber":5,"description":"State the hyperbola.","workingLatex":"\\tfrac{(y + 3)^2}{4} - (x - 1)^2 = 1","explanation":"Centre \\((1, -3)\\), opening vertically."}],"finalAnswer":"\\(\\tfrac{(y + 3)^2}{4} - (x - 1)^2 = 1\\)."}},
  {"id":"y2pe2-068","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 20","difficulty":"Foundation","questionText":"A curve has parametric equations \\(x = 2\\sin t,\\ y = 2\\sin t\\). Find its Cartesian equation.","marks":2,"examStyle":false,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Compare the two equations.","workingLatex":"x = 2\\sin t,\\quad y = 2\\sin t","explanation":"Both coordinates are the *same* expression, so they are always equal."},{"stepNumber":2,"description":"Deduce the relation.","workingLatex":"y = x","explanation":"Since \\(x\\) and \\(y\\) equal the same thing, \\(y = x\\)."},{"stepNumber":3,"description":"Find the range.","workingLatex":"-2 \\le 2\\sin t \\le 2","explanation":"As \\(\\sin t \\in [-1, 1]\\), so \\(x = 2\\sin t \\in [-2, 2]\\)."},{"stepNumber":4,"description":"State the restricted line.","workingLatex":"y = x,\\ -2 \\le x \\le 2","explanation":"Only this segment of the line \\(y = x\\) is traced."}],"finalAnswer":"\\(y = x\\) (restricted to \\(-2 \\le x \\le 2\\))."}},
  {"id":"y2pe2-069","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 49","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = \\cos t,\\ y = 2 + \\sin t\\). Describe the curve.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Plan the elimination.","workingLatex":"\\cos^2 t + \\sin^2 t = 1","explanation":"A unit circle shifted up by 2."},{"stepNumber":2,"description":"Isolate \\(\\cos t\\) and \\(\\sin t\\).","workingLatex":"\\cos t = x,\\quad \\sin t = y - 2","explanation":"\\(x\\) is already \\(\\cos t\\); subtract 2 from \\(y\\)."},{"stepNumber":3,"description":"Square and add.","workingLatex":"x^2 + (y - 2)^2 = 1","explanation":"Apply the identity."},{"stepNumber":4,"description":"Describe the curve.","workingLatex":"\\text{circle: centre } (0, 2),\\ r = 1","explanation":"A circle of radius 1 centred at \\((0, 2)\\)."}],"finalAnswer":"Circle centre \\((0, 2)\\), radius 1."}},
  {"id":"y2pe2-070","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 50","difficulty":"Standard","questionText":"A curve has parametric equations \\(x = \\tan t,\\ y = 2 + \\sec t\\). Find its Cartesian equation.","marks":3,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Choose the right identity.","workingLatex":"\\sec^2 t - \\tan^2 t = 1","explanation":"Sec and tan present."},{"stepNumber":2,"description":"Isolate \\(\\tan t\\) and \\(\\sec t\\).","workingLatex":"\\tan t = x,\\quad \\sec t = y - 2","explanation":"\\(x\\) is already \\(\\tan t\\); subtract 2 from \\(y\\)."},{"stepNumber":3,"description":"Square and subtract (sec² first).","workingLatex":"(y - 2)^2 - x^2 = \\sec^2 t - \\tan^2 t = 1","explanation":"Apply the identity."},{"stepNumber":4,"description":"State the hyperbola.","workingLatex":"(y - 2)^2 - x^2 = 1","explanation":"Centred at \\((0, 2)\\), opening vertically."}],"finalAnswer":"\\((y - 2)^2 - x^2 = 1\\)."}},
  {"id":"y2pe2-071","topicRef":"y2pe2","topicTitle":"Using Trigonometric Identities 71","difficulty":"Challenge","questionText":"For the curve \\(x = 2\\cos\\theta - \\sin\\theta,\\ y = \\cos\\theta + 2\\sin\\theta\\), find \\(x^2 + y^2\\).","marks":4,"examStyle":true,"yearCreated":2026,"tags":["parametric"],"workedSolution":{"steps":[{"stepNumber":1,"description":"Set up \\(x^2 + y^2\\).","workingLatex":"x^2 + y^2 = (2\\cos\\theta - \\sin\\theta)^2 + (\\cos\\theta + 2\\sin\\theta)^2","explanation":"Write out both squares; the cross terms will cancel."},{"stepNumber":2,"description":"Expand the first square.","workingLatex":"x^2 = 4\\cos^2\\theta - 4\\sin\\theta\\cos\\theta + \\sin^2\\theta","explanation":"Apply \\((a - b)^2 = a^2 - 2ab + b^2\\)."},{"stepNumber":3,"description":"Expand the second square.","workingLatex":"y^2 = \\cos^2\\theta + 4\\sin\\theta\\cos\\theta + 4\\sin^2\\theta","explanation":"Apply \\((a + b)^2\\); the cross term is \\(+4\\sin\\theta\\cos\\theta\\)."},{"stepNumber":4,"description":"Add to cancel the cross terms.","workingLatex":"x^2 + y^2 = 5\\cos^2\\theta + 5\\sin^2\\theta","explanation":"The \\(-4\\sin\\theta\\cos\\theta\\) and \\(+4\\sin\\theta\\cos\\theta\\) cancel; the squares combine."},{"stepNumber":5,"description":"Apply the identity.","workingLatex":"x^2 + y^2 = 5","explanation":"\\(5(\\cos^2\\theta + \\sin^2\\theta) = 5\\): a circle of radius \\(\\sqrt 5\\)."}],"finalAnswer":"5 (so circle of radius \\(\\sqrt 5\\))."}},
];
